#[derive(Debug, Clone, serde::Serialize)]
pub struct FitConfig {
    pub seed: u64,
    // defaults: support threshold 5 + 0.5 per torsion (calibrated on synthetic maps with known
    // absent residues); 384 samples x 8 Heun steps (same core/supported recovery and validity as
    // 768 x 32 on 6 X-ray and cryo-EM sites x 3 seeds, at ~1/8 of the network evaluations)
    pub n_samples: usize,
    pub n_basins: usize,
    pub refine_steps: usize,
    pub refine_lr: f64,
    pub polish_top: usize,
    pub polish_steps: usize,
    pub polish_lr: f64,
    pub support_base: f64,
    pub support_per_torsion: f64,
    pub n_completions: usize,
    pub completion_guidance: f32,
    pub alt_margin: f64,
    /// known positions stay the model against a basin that explains the map worse by more than
    /// this (log-likelihood units), whatever the priors say (see `keeps_known`)
    pub known_guard: f64,
    /// ... and against a basin that keeps less than this share of their log-likelihood: where
    /// the map is weak the whole log-likelihood is smaller than `known_guard`
    pub known_share: f64,
    pub flow_steps: usize,
    pub guidance_scale: f64,
    pub guidance_start: f64,
    /// contact-energy weight (w_env = w_self) during the search
    pub search_clash_weight: f64,
    /// contact-energy weight of the final objective (None: keep the search weight). Every retained
    /// basin is re-scored with it, the best few are refined under it, and selection, support,
    /// completions and alternatives use it (continuation; one objective for all final comparisons).
    pub final_clash_weight: Option<f64>,
    pub steric_steps: usize,
    pub steric_lr: f64,
    /// Contact-validity escalation: while the selected pose's raw contact energy
    /// (E_env + E_self, squared floor violations; in the Cartesian stage its deepest single
    /// contact, `SiteProblem::worst_contact`) exceeds `contact_tolerance`, multiply the final
    /// contact weight by 10, re-score every basin, refine the best few and re-select (at most
    /// `max_escalations` times). The floors sit >= 0.08 A above the validator's van der Waals
    /// limits, so a tolerance of 0.08^2 guarantees no single pair violates them.
    pub contact_tolerance: f64,
    pub max_escalations: usize,
    /// Restrained Cartesian refinement of every retained basin (0: torsion space only), at
    /// `cartesian_clash_weight` with the same contact escalation; basins are then ranked on
    /// objective + restraint energy (`cartesian.rs`).
    pub cartesian_steps: usize,
    pub cartesian_lr: f64,
    pub cartesian_clash_weight: f64,
    pub restraints: RestraintOptions,
    /// final refinement of the selected basin with the map weighted up (`DataWeight`; None: off).
    /// Basins are ranked and selected at weight 1 as before.
    pub data_weight: Option<DataWeight>,
    /// escalate the contact weight in torsion space too (re-ranking every basin under it)
    pub torsion_escalation: bool,
    pub cartesian_escalation: Escalation,
    /// before choosing basins, briefly refine this many times `n_basins` of the best guided samples
    /// and choose among the refined ones (0: choose among the unrefined samples)
    pub pre_refine: usize,
    pub pre_refine_steps: usize,
    /// re-generate around the best `renoise_basins` basins after the search (SDEdit): each one's
    /// torsions are taken back to `renoise_t` on the path from fresh noise and integrated again with
    /// the map's guidance, `renoise_per_basin` times (0 basins: off); repeated `renoise_rounds`
    /// times, each round from the best poses so far
    pub renoise_basins: usize,
    pub renoise_per_basin: usize,
    pub renoise_t: f64,
    pub renoise_rounds: usize,
    /// core-first search (`search::core_first`): `core_first_fraction * n_samples` guided samples
    /// scored on the core only, the best `core_first_cores` distinct cores completed
    /// `core_first_per_core` times each under the full objective (0: off)
    pub core_first_fraction: f64,
    pub core_first_cores: usize,
    pub core_first_per_core: usize,
    /// branch re-noising (`search::branch_renoise`) of the best `branch_basins` poses after the
    /// re-noise rounds, `branch_per_branch` times per subtree (0 basins: off)
    pub branch_basins: usize,
    pub branch_per_branch: usize,
    /// evaluation only: poses added to the basins after the search (refined like them), e.g. the
    /// deposited glycan's (`evaluation::deposited_pose`), to measure the best the pipeline reaches
    #[serde(skip)]
    pub extra_starts: Vec<Pose>,
    /// known atom positions (`known`): moved onto them, the extra starts and the
    /// `coordinate_bases` lowest basins join the Cartesian refinement as basins of their own
    #[serde(skip)]
    pub coordinate_start: Option<CoordinateStart>,
    pub coordinate_bases: usize,
}

/// Standard deviation of the springs that hold known atoms in place while their covalent
/// geometry is repaired (A): loose against a bond (0.02 A), stiff against the drift of a residue.
pub const KNOWN_TETHER: f64 = 0.1;

/// The same for atoms that have no known position of their own (A): those of a residue placed as
/// a rigid body on known atoms it cannot match (another anomer, a ring out of its chair), and
/// those the known model lacks. Such a residue moves as a whole to mend its links; held as
/// tightly as a known atom it would mend them by bending its ring instead.
pub const PLACED_TETHER: f64 = 0.5;

/// Contact-weight escalation of the Cartesian stage.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Escalation {
    /// refine and re-rank every basin under the escalated weight
    Rerank,
    /// rank once at the final contact weight; only the selected basin is refined under higher
    /// weights (and re-scored at the final weight), so contacts never dominate the ranking
    Selected,
}

