/// GlycoFlow marginal prior settings (`MarginalPrior.from_model`).
#[derive(Debug, Clone, serde::Serialize)]
pub struct PriorConfig {
    pub enabled: bool,
    pub n_samples: usize,
    pub steps: usize,
    pub bandwidth_deg: f64,
    pub seed: u64,
    /// samples of glycans already drawn, shared between fits (a batch of sites repeats a few
    /// glycans): the free glycan's samples depend on the glycan and these settings only
    #[serde(skip)]
    pub cache: Option<PriorCache>,
}

/// Free-glycan torsion samples by glycan and sampling settings (`PriorConfig::cache`).
pub type PriorCache = std::sync::Arc<
    std::sync::Mutex<std::collections::HashMap<Vec<u32>, std::sync::Arc<Vec<Vec<f64>>>>>,
>;

/// Everything `sample_free` reads: the glycan's tokens, torsions and local geometries, and the
/// sampling settings.
fn prior_key(problem: &SiteProblem, sampler: &Sampler, config: &PriorConfig) -> Vec<u32> {
    let mut key = vec![
        config.n_samples as u32,
        config.steps as u32,
        config.seed as u32,
        (config.seed >> 32) as u32,
        problem.batch.map_or(0, |b| b as u32 + 1),
        sampler.tokens.len() as u32,
    ];
    key.extend(sampler.tokens.iter().flatten());
    key.extend(sampler.topology.quads.iter().flatten().map(|&i| i as u32));
    for template in &problem.glycan.templates {
        key.extend(template.iter().flatten().map(|v| v.to_bits()));
    }
    key
}

impl Default for PriorConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            n_samples: 512,
            steps: 16,
            bandwidth_deg: 12.0,
            seed: 1234,
            cache: None,
        }
    }
}

/// Sigma calibration (`diagnostics.calibrate_sigma`): the atom width at which the protein shell
/// 4-12 A from the link atom, scored as if it were the glycan against the remaining environment,
/// best explains the map (partial correlation). Independent of any glycan candidate.
#[derive(Debug, Clone, serde::Serialize)]
pub struct SigmaCalibration {
    pub selected: f64,
    pub curve: Vec<(f64, f64)>,
}

pub const SIGMA_GRID: [f64; 7] = [0.6, 0.8, 1.0, 1.2, 1.4, 1.7, 2.0];

fn env_atoms(site: &Site, filter: impl Fn(&[f64; 3]) -> bool) -> Vec<SiteEnvironmentAtom> {
    site.environment
        .iter()
        .filter(|a| filter(&a.position))
        .map(|a| SiteEnvironmentAtom {
            position: a.position,
            atomic_number: a.atomic_number,
        })
        .collect()
}

pub fn calibrate_sigma(site: &Site, map: &DensityMap, resolution: f64) -> Result<SigmaCalibration> {
    let (inner, outer) = (4.0f32, 12.0f32);
    let link = site.anchor[2];
    // float32 distances, as the reference computes them on float32 arrays
    let in_shell = |p: &[f64; 3]| {
        let d = (0..3)
            .map(|k| (p[k] as f32 - link[k] as f32).powi(2))
            .fold(0f32, |a, b| a + b)
            .sqrt();
        d > inner && d < outer
    };
    let shell = env_atoms(site, in_shell);
    let rest = env_atoms(site, |p| !in_shell(p));
    let positions: Vec<[f64; 3]> = shell.iter().map(|a| a.position).collect();
    let z: Vec<f64> = shell.iter().map(|a| a.atomic_number).collect();
    let curve = SIGMA_GRID
        .par_iter()
        .map(|&sigma| {
            let options = SiteLikelihoodOptions {
                sigma_angstrom: sigma,
                spacing_angstrom: 0.5,
                radius_angstrom: outer as f64 + 2.0,
                resolution_angstrom: resolution,
                periodic: map.is_full_unit_cell(),
                independent_volume: Some(1.0),
                solvent_distance: Some(reglyco_density::site_likelihood::SOLVENT_DISTANCE),
            };
            let lik = SiteLikelihood::from_map(map, link, &rest, options)?;
            Ok((
                sigma,
                lik.evaluate(&positions, &z, None).partial_correlation,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    let selected = curve
        .iter()
        .fold(
            (f64::NAN, f64::MIN),
            |best, &(s, c)| if c > best.1 { (s, c) } else { best },
        )
        .0;
    Ok(SigmaCalibration { selected, curve })
}

/// Build the density fitting problem of a site.
pub fn density_problem(
    site: &Site,
    model: &GlycoflowModel,
    map: &DensityMap,
    sigma: f64,
    resolution: f64,
    options: &ProblemOptions,
) -> Result<SiteProblem> {
    let mut glycan = build_glycan(
        &model.library,
        &site.sequence.sequence,
        options.n_templates,
        options.template_seed,
    )?;
    let generated = options.ring_source.generates(model);
    if generated {
        crate::problem::generate_ring_templates(&mut glycan, model, 16, options.template_seed)?;
    }
    if options.chair_rings {
        crate::ring::chair_templates(&mut glycan);
    }
    // C-mannose: 1C4 in crystals, 4C1 in GlycoFlow's library; odd templates take the other chair
    if crate::anchor::anchor(&site.residue_name).is_some_and(|a| a.both_chairs) {
        crate::ring::flip_root_chair(&mut glycan, |t| t % 2 == 1);
    }
    let radius = options
        .region_radius
        .unwrap_or_else(|| max_span(&glycan) + 2.5);
    let lik_options = SiteLikelihoodOptions {
        sigma_angstrom: sigma,
        spacing_angstrom: 0.5,
        radius_angstrom: radius,
        resolution_angstrom: resolution,
        periodic: map.is_full_unit_cell(),
        independent_volume: None,
        solvent_distance: Some(reglyco_density::site_likelihood::SOLVENT_DISTANCE),
    };
    let env = env_atoms(site, |_| true);
    let likelihood = SiteLikelihood::from_map(map, site.anchor[2], &env, lik_options)?;
    let grid_box = (
        likelihood.obs_blur.origin,
        likelihood.obs_blur.spacing,
        likelihood.obs_blur.dims,
    );
    let observation: Box<dyn Observation> = Box::new(DensityObservation::new(likelihood));
    SiteProblem::with_rings(
        site,
        glycan,
        &model.meta.vocab,
        observation,
        grid_box,
        radius,
        options,
        generated,
    )
}

/// Candidate-independent constants of a density problem (box, protein-only fit, noise).
#[derive(Debug, Clone, serde::Serialize)]
pub struct DensityConstants {
    pub radius: f64,
    pub origin: [f64; 3],
    pub dims: [usize; 3],
    pub spacing: f64,
    pub sigma: f64,
    /// environment-only fit (a0, b0, bulk-solvent level c_s0)
    pub theta: [f64; 3],
    pub sse0: f64,
    pub noise_variance: f64,
    /// independent-sample volume (A^3) from the residual autocorrelation
    pub independent_volume: f64,
    /// empirical noise inflation (decoy null, >= 1)
    pub inflation: f64,
}

pub fn density_constants(problem: &SiteProblem) -> Option<DensityConstants> {
    let lik = problem.observation.density()?;
    Some(DensityConstants {
        radius: lik.radius,
        origin: lik.obs_blur.origin,
        dims: lik.obs_blur.dims,
        spacing: lik.obs_blur.spacing,
        sigma: lik.sigma,
        theta: lik.theta,
        sse0: lik.sse0,
        noise_variance: lik.noise_variance,
        independent_volume: lik.independent_volume,
        inflation: lik.inflation,
    })
}

/// Draw GlycoFlow samples of the free glycan and build the marginal prior.
pub fn build_prior(
    problem: &SiteProblem,
    sampler: &Sampler,
    config: &PriorConfig,
) -> Result<MarginalPrior> {
    let draw = || {
        sample_free(
            problem,
            sampler,
            config.n_samples,
            config.steps,
            Method::Euler,
            config.seed,
        )
    };
    let taus = match &config.cache {
        Some(cache) => {
            let key = prior_key(problem, sampler, config);
            let hit = cache.lock().unwrap().get(&key).cloned();
            match hit {
                Some(taus) => taus,
                None => {
                    let taus = std::sync::Arc::new(draw()?);
                    cache.lock().unwrap().insert(key, taus.clone());
                    taus
                }
            }
        }
        None => std::sync::Arc::new(draw()?),
    };
    // over the torsions the structure determines (`SiteProblem::heavy_torsions`)
    Ok(
        MarginalPrior::new(taus.concat(), problem.n_torsions, config.bandwidth_deg)
            .with_torsions(problem.heavy_torsions()),
    )
}

/// One retained basin.
#[derive(Debug, Clone)]
pub struct Basin {
    pub pose: Pose,
    pub x: Vec<V3>,
    pub terms: Terms,
    /// objective before refinement
    pub unrefined: f64,
    /// restraint energy of the Cartesian stage (0 without it); basins are ranked on
    /// terms.total + e_restraint
    pub e_restraint: f64,
    /// refined from known atom positions (`FitConfig::coordinate_start`), not from a search pose
    pub from_known: bool,
    /// terms.total + e_restraint when the basins were ranked: the final refinement of the
    /// selected basin (`FitConfig::data_weight`) changes its terms, not its rank
    pub objective: f64,
    /// weight of the map in that final refinement (1: not refined further)
    pub data_weight: f64,
    /// the pucker template its restraints take their rings from (a pose measured on known
    /// positions may name another)
    pub template: usize,
}

pub struct FitOutcome {
    pub basins: Vec<Basin>,
    /// basin indices by objective
    pub order: Vec<usize>,
    pub best: usize,
    pub support: Vec<SubtreeSupport>,
    pub free_torsions: Vec<bool>,
    pub completions: Vec<Completion>,
    /// basins within `alt_margin` of the best (the best included), by objective
    pub alternatives: Vec<usize>,
    pub counters: CounterSnapshot,
    pub wall_seconds: f64,
    /// contact weight of the final objective (after any escalation)
    pub final_contact_weight: f64,
    /// how far the selected pose is from what GlycoFlow generates (None without a prior)
    pub prior_deviation: Option<PriorDeviation>,
}

/// Prior diagnostics of a placed pose: torsions measured on the coordinates.
pub fn prior_deviation(problem: &SiteProblem, x: &[V3]) -> Option<PriorDeviation> {
    let prior = problem.prior.as_ref()?;
    let quads = &problem.glycan.topology.quads;
    let tau: Vec<f64> = quads
        .iter()
        .map(|q| crate::problem::dihedral(x[q[0]], x[q[1]], x[q[2]], x[q[3]]))
        .collect();
    let pct = prior.percentiles(&tau);
    // torsions the structure determines: a hydroxyl rotamer (an all-atom model's polar hydrogen)
    // is invisible to the map and absent from deposits, so it is left out of every diagnostic
    let heavy = problem.heavy_torsions();
    let names = &problem.glycan.atom_names;
    let rare_torsions = quads
        .iter()
        .enumerate()
        .filter(|(t, _)| heavy[*t] && pct[*t] < RARE_PERCENTILE)
        .map(|(t, q)| RareTorsion {
            torsion: format!(
                "{}:{}",
                problem.glycan.res_paths[q[1]],
                q.iter()
                    .map(|&i| names[i].as_str())
                    .collect::<Vec<_>>()
                    .join("-")
            ),
            degrees: tau[t].to_degrees(),
            percentile: pct[t],
        })
        .collect();
    Some(PriorDeviation {
        e_prior: prior.energy_on(&tau, &heavy),
        rarity: prior.rarity_on(&tau, &heavy),
        rare_torsions,
        n_torsions: tau.len(),
    })
}

/// Fit one site (`pipeline.fit_site`). The problem's prior (if any) must already be set. The
/// problem is left with the final contact weights, so later evaluations use the final objective.
pub fn fit_site(
    problem: &mut SiteProblem,
    sampler: &Sampler,
    config: &FitConfig,
) -> Result<FitOutcome> {
    if config.n_samples == 0 || config.n_basins == 0 || config.flow_steps == 0 {
        return Err(invalid(
            "samples, basins and flow steps must each be at least 1",
        ));
    }
    let started = Instant::now();
    problem.w_env = config.search_clash_weight;
    problem.w_self = config.search_clash_weight;
    let observer = problem.observer.clone();
    let observer = observer.get();
    // the core placed on its own, then completed (needs the problem mutably: it scores the core's
    // atoms only while it samples)
    let core_samples = (config.core_first_fraction * config.n_samples as f64).round() as usize;
    let core_first = if core_samples > 0 {
        let t0 = Instant::now();
        if let Some(o) = observer {
            o.stage("core first");
        }
        let r = crate::search::core_first(
            problem,
            sampler,
            core_samples,
            config.core_first_cores,
            config.core_first_per_core,
            config
                .final_clash_weight
                .unwrap_or(config.search_clash_weight),
            config.flow_steps,
            config.guidance_scale,
            config.guidance_start,
            config.refine_steps,
            config.refine_lr,
            config.seed,
        )?;
        problem.counter.add_stage("core first", t0);
        r
    } else {
        (Vec::new(), Vec::new())
    };
    // search on the (smoother) search weights
    let (mut poses, mut energies, mut unrefined, mut sources) = {
        let problem: &SiteProblem = problem;
        let c = &problem.counter;
        let r = method_b(
            problem,
            sampler,
            config.n_samples,
            config.n_basins,
            config.refine_steps,
            config.refine_lr,
            config.flow_steps,
            config.guidance_scale,
            config.guidance_start,
            config.seed,
            config.pre_refine,
            config.pre_refine_steps,
        )?;
        let mut poses = r.poses;
        let mut energies = r.energies;
        let mut sources = r.sources;
        // new poses join the basins beside them, never in place of one (see the re-noise rounds)
        let add = |poses: &mut Vec<Pose>,
                   energies: &mut Vec<f64>,
                   sources: &mut Vec<usize>,
                   (p, e): (Vec<Pose>, Vec<f64>),
                   k: usize| {
            let x: Vec<Vec<V3>> = p.par_iter().map(|p| problem.place(p)).collect();
            let keep = crate::search::distinct(problem, &x, &e, k, 0.5);
            poses.extend(keep.iter().map(|&i| p[i].clone()));
            energies.extend(keep.iter().map(|&i| e[i]));
            sources.resize(poses.len(), usize::MAX);
        };
        if !core_first.0.is_empty() {
            add(
                &mut poses,
                &mut energies,
                &mut sources,
                core_first,
                2 * config.core_first_cores,
            );
        }
        for round in 0..if config.renoise_basins > 0 {
            config.renoise_rounds
        } else {
            0
        } {
            let t0 = Instant::now();
            if let Some(o) = observer {
                o.stage("re-noise");
            }
            let (p, e) = crate::search::renoise(
                problem,
                sampler,
                &poses,
                &energies,
                config.renoise_basins,
                config.renoise_per_basin,
                config.renoise_t,
                config.flow_steps,
                config.guidance_scale,
                config.guidance_start,
                config.refine_steps,
                config.refine_lr,
                config.seed.wrapping_add(round as u64),
            )?;
            // add the best new poses beside every basin, never in place of one: the final
            // objective ranks differently from the search energy, so a re-noised pose that wins
            // here can refine to a worse optimum than the basin it would displace. A pose may sit
            // in a basin it came from (a second start there); a re-noised basin has no guided
            // sample of its own to replay.
            let x: Vec<Vec<V3>> = p.par_iter().map(|p| problem.place(p)).collect();
            let keep = crate::search::distinct(problem, &x, &e, 2 * config.renoise_basins, 0.5);
            poses.extend(keep.iter().map(|&i| p[i].clone()));
            energies.extend(keep.iter().map(|&i| e[i]));
            sources.resize(poses.len(), usize::MAX);
            c.add_stage("re-noise", t0);
        }
        if config.branch_basins > 0 {
            let t0 = Instant::now();
            if let Some(o) = observer {
                o.stage("branch re-noise");
            }
            let r = crate::search::branch_renoise(
                problem,
                sampler,
                &poses,
                &energies,
                config.branch_basins,
                config.branch_per_branch,
                config.flow_steps,
                config.guidance_scale,
                config.guidance_start,
                config.refine_steps,
                config.refine_lr,
                config.seed.wrapping_add(0xB2A9),
            )?;
            add(&mut poses, &mut energies, &mut sources, r, 8);
            c.add_stage("branch re-noise", t0);
        }
        if !config.extra_starts.is_empty() {
            for (pose, e) in refine(
                problem,
                &config.extra_starts,
                config.refine_steps,
                config.refine_lr,
            ) {
                poses.push(pose);
                energies.push(e);
            }
            sources.resize(poses.len(), usize::MAX);
        }
        let t0 = Instant::now();
        if let Some(o) = observer {
            o.stage("polish");
        }
        polish_top(
            problem,
            &mut poses,
            &mut energies,
            config.polish_top,
            config.polish_steps,
            config.polish_lr,
        );
        c.add_stage("polish", t0);
        if let Some(o) = observer {
            o.basins("polish", &sources, &poses, &energies);
        }
        let mut unrefined = r.unrefined;
        unrefined.resize(poses.len(), f64::NAN);
        (poses, energies, unrefined, sources)
    };
    // final objective: re-score every basin, refine the best few under it; escalate the contact
    // weight while the selected pose still violates the contact floors
    let mut final_contact_weight = problem.w_env;
    if let Some(w0) = config.final_clash_weight {
        let mut w = w0;
        let rounds = if config.torsion_escalation {
            config.max_escalations
        } else {
            0
        };
        for round in 0..=rounds {
            problem.w_env = w;
            problem.w_self = w;
            final_contact_weight = w;
            let problem: &SiteProblem = problem;
            let t0 = Instant::now();
            if let Some(o) = observer {
                o.stage(if round == 0 {
                    "steric polish"
                } else {
                    "steric escalation"
                });
            }
            energies = poses
                .par_iter()
                .map(|pose| problem.evaluate(pose, false).terms.total)
                .collect();
            problem.counter.add_objective(poses.len());
            polish_top(
                problem,
                &mut poses,
                &mut energies,
                config.polish_top,
                config.steric_steps,
                config.steric_lr,
            );
            let stage = if round == 0 {
                "steric polish"
            } else {
                "steric escalation"
            };
            problem.counter.add_stage(stage, t0);
            if let Some(o) = observer {
                o.basins(stage, &sources, &poses, &energies);
            }
            let best = (0..energies.len())
                .min_by(|&a, &b| energies[a].total_cmp(&energies[b]))
                .unwrap_or(0);
            let t = problem.evaluate(&poses[best], false).terms;
            if t.e_env + t.e_self <= config.contact_tolerance {
                break;
            }
            w *= 10.0;
        }
    }
    // restrained Cartesian refinement of every basin, with the same contact escalation
    let mut cartesian: Option<Vec<CartesianFit>> = None;
    let n_search = poses.len();
    if config.cartesian_steps > 0 {
        let t0 = Instant::now();
        if let Some(o) = observer {
            o.stage("cartesian");
        }
        let mut xs: Vec<Vec<V3>> = {
            let problem: &SiteProblem = problem;
            poses.par_iter().map(|p| problem.place(p)).collect()
        };
        if let Some(start) = &config.coordinate_start {
            // the extra starts are the last search poses
            let mut bases: Vec<usize> = (n_search - config.extra_starts.len()..n_search).collect();
            let mut order: Vec<usize> = (0..n_search).collect();
            order.sort_by(|&a, &b| energies[a].total_cmp(&energies[b]));
            let lowest: Vec<usize> = order
                .into_iter()
                .filter(|i| !bases.contains(i))
                .take(config.coordinate_bases)
                .collect();
            bases.extend(lowest);
            // every residue as a rigid body on its known atoms (ideal geometry in the known
            // place, whatever the geometry of the known model)
            let placed = CoordinateStart {
                x: start.x.clone(),
                exact: vec![false; start.exact.len()],
            };
            // an atom placed with its residue, or not known at all, is not where it will end
            let tether: Vec<f64> = (0..xs[0].len())
                .map(|i| match start.exact.get(i) {
                    Some(true) => KNOWN_TETHER,
                    _ => PLACED_TETHER,
                })
                .collect();
            for b in bases {
                // on the pucker template closest to the known positions
                let mut pose = poses[b].clone();
                pose.template = start_template(problem, start, &pose);
                let base = if pose.template == poses[b].template {
                    xs[b].clone()
                } else {
                    problem.place(&pose)
                };
                // the covalent geometry of both repaired in place before the map is asked: a
                // known model far off the restraint targets (another dictionary, a loose
                // refinement, residues placed as rigid bodies) would otherwise spend the
                // refinement on its geometry
                let restraints = Restraints::new(problem, pose.template, &config.restraints);
                for start in [start, &placed] {
                    let x = hybrid(problem, &base, start);
                    xs.push(restraints.regularise(&x, &problem.movable[..x.len()], &tether));
                    poses.push(pose.clone());
                    energies.push(energies[b]);
                    unrefined.push(f64::NAN);
                    sources.push(usize::MAX);
                }
            }
        }
        let templates: Vec<usize> = poses.iter().map(|p| p.template).collect();
        let w0 = config.cartesian_clash_weight;
        // no single contact deeper than the tolerance: many shallow ones (a glycan hydrogen-bonded
        // to its neighbours all round) stay clear of the validator's limits and do not escalate
        let clear = |problem: &SiteProblem, f: &CartesianFit| {
            problem.worst_contact(&f.x) <= config.contact_tolerance
        };
        // the basin the fit would return: the lowest, or the lowest from known positions when
        // the map cannot tell the two apart (see the selection below)
        let selected = |fits: &[CartesianFit]| {
            let lowest = |range: std::ops::Range<usize>| {
                range.min_by(|&a, &b| fits[a].total.total_cmp(&fits[b].total))
            };
            let best = lowest(0..fits.len()).unwrap_or(0);
            lowest(n_search..fits.len())
                .filter(|&k| {
                    let objective = fits[k].total - fits[best].total;
                    keeps_known(
                        config,
                        objective,
                        fits[k].terms.loglik,
                        fits[best].terms.loglik,
                    )
                })
                .unwrap_or(best)
        };
        match config.cartesian_escalation {
            Escalation::Rerank => {
                let mut w = w0;
                for _ in 0..=config.max_escalations {
                    problem.w_env = w;
                    problem.w_self = w;
                    final_contact_weight = w;
                    let fits = cartesian_refine_all(
                        problem,
                        &xs,
                        &templates,
                        config.cartesian_steps,
                        config.cartesian_lr,
                        &config.restraints,
                    );
                    let ok = clear(problem, &fits[selected(&fits)]);
                    xs = fits.iter().map(|f| f.x.clone()).collect();
                    cartesian = Some(fits);
                    if ok {
                        break;
                    }
                    w *= 10.0;
                }
            }
            Escalation::Selected => {
                problem.w_env = w0;
                problem.w_self = w0;
                final_contact_weight = w0;
                let mut fits = cartesian_refine_all(
                    problem,
                    &xs,
                    &templates,
                    config.cartesian_steps,
                    config.cartesian_lr,
                    &config.restraints,
                );
                // a basin that takes the selection from an escalated one starts from the base
                // weight again
                let mut attempts = vec![0usize; fits.len()];
                loop {
                    let b = selected(&fits);
                    if clear(problem, &fits[b]) || attempts[b] == config.max_escalations {
                        break;
                    }
                    attempts[b] += 1;
                    let factor = 10f64.powi(attempts[b] as i32);
                    let w = w0 * factor;
                    problem.w_env = w;
                    problem.w_self = w;
                    final_contact_weight = w;
                    // restraints escalate with the contacts (sd / sqrt(factor)): only the density
                    // is down-weighted, so clearing a contact never distorts the ring geometry
                    let r = &config.restraints;
                    let scaled = RestraintOptions {
                        sd_bond: r.sd_bond / factor.sqrt(),
                        sd_angle: r.sd_angle / factor.sqrt(),
                        sd_volume: r.sd_volume / factor.sqrt(),
                        sd_ring: r.sd_ring / factor.sqrt(),
                        sd_amide: r.sd_amide / factor.sqrt(),
                    };
                    let pass = format!("escalation x{factor}");
                    let up = cartesian_refine_traced(
                        problem,
                        &fits[b].x,
                        templates[b],
                        config.cartesian_steps,
                        config.cartesian_lr,
                        &scaled,
                        Some((b, pass.as_str())),
                    );
                    problem.counter.add_objective_grad(config.cartesian_steps);
                    problem.w_env = w0;
                    problem.w_self = w0;
                    // re-scored at the ranking weight
                    fits[b] = cartesian_refine(
                        problem,
                        &up.x,
                        templates[b],
                        0,
                        config.cartesian_lr,
                        &config.restraints,
                    );
                }
                cartesian = Some(fits);
            }
        }
        problem.counter.add_stage("cartesian", t0);
    }
    let problem: &SiteProblem = problem;
    let c = &problem.counter;
    let t0 = Instant::now();
    if let Some(o) = observer {
        o.stage("support+complete");
    }
    let mut basins: Vec<Basin> = match cartesian {
        Some(fits) => {
            energies = fits.iter().map(|f| f.total).collect();
            poses
                .into_iter()
                .zip(fits)
                .zip(&unrefined)
                .enumerate()
                .map(|(k, ((mut pose, fit), &unrefined))| {
                    pose.psi = fit.psi;
                    let template = pose.template;
                    // a basin refined from known positions: the pose is measured on it
                    if k >= n_search {
                        pose = pose_from_atoms(problem, |i| Some(fit.x[i]), &pose);
                    }
                    Basin {
                        pose,
                        x: fit.x,
                        terms: fit.terms,
                        unrefined,
                        e_restraint: fit.e_restraint,
                        from_known: k >= n_search,
                        objective: fit.total,
                        data_weight: 1.0,
                        template,
                    }
                })
                .collect()
        }
        None => {
            let evaluated: Vec<_> = poses
                .par_iter()
                .map(|p| problem.evaluate(p, false))
                .collect();
            poses
                .into_iter()
                .zip(evaluated)
                .zip(&unrefined)
                .map(|((pose, ev), &unrefined)| Basin {
                    template: pose.template,
                    pose,
                    x: ev.x,
                    objective: ev.terms.total,
                    terms: ev.terms,
                    unrefined,
                    e_restraint: 0.0,
                    from_known: false,
                    data_weight: 1.0,
                })
                .collect()
        }
    };
    if let Some(o) = observer {
        let poses: Vec<Pose> = basins.iter().map(|b| b.pose.clone()).collect();
        o.basins("final", &sources, &poses, &energies);
    }
    let mut order: Vec<usize> = (0..energies.len()).collect();
    order.sort_by(|&a, &b| energies[a].total_cmp(&energies[b]));
    // known positions stay the model when the map cannot tell them from the lowest basin
    let lowest = order[0];
    let mut best = order
        .iter()
        .copied()
        .find(|&i| basins[i].from_known)
        .filter(|&i| {
            let (known, other) = (basins[i].terms.loglik, basins[lowest].terms.loglik);
            keeps_known(config, energies[i] - energies[lowest], known, other)
        })
        .unwrap_or(lowest);
    // the final refinement of both; the known positions come back when the map then tells for
    // them: at the weight of the search a model on them gives up density for its geometry
    let known = order.iter().copied().find(|&i| basins[i].from_known);
    if let Some(k) = known.filter(|&k| k != best && config.data_weight.is_some()) {
        weigh_up(problem, config, &mut basins[best], best);
        weigh_up(problem, config, &mut basins[k], k);
        let (known, other) = (basins[k].terms.loglik, basins[best].terms.loglik);
        if map_tells_for_known(config, known, other) {
            best = k;
        }
    }
    let mut outcome = FitOutcome {
        basins,
        order,
        best,
        support: Vec::new(),
        free_torsions: Vec::new(),
        completions: Vec::new(),
        alternatives: Vec::new(),
        counters: c.snapshot(),
        wall_seconds: 0.0,
        final_contact_weight,
        prior_deviation: None,
    };
    reselect(problem, sampler, config, &mut outcome, best)?;
    c.add_stage("support+complete", t0);
    outcome.counters = c.snapshot();
    outcome.wall_seconds = started.elapsed().as_secs_f64();
    Ok(outcome)
}

/// Whether the lowest basin from known positions stays the model against the lowest basin of
/// all, given its objective and its log-likelihood relative to that one: when the map cannot tell
/// the two apart, or when the map tells for the known positions (`map_tells_for_known`) and
/// only the priors tell against them. The priors take the protein as it is given, and a misplaced
/// side chain at the site would otherwise move a well-placed glycan out of its density.
fn keeps_known(config: &FitConfig, objective: f64, known: f64, other: f64) -> bool {
    objective <= config.alt_margin || map_tells_for_known(config, known, other)
}

/// Whether the map tells for known positions (log-likelihood `known`) against another basin
/// (`other`): by more than `known_guard`, or the other keeps less than `known_share` of it
/// (a share only means something of a log-likelihood above zero).
pub(crate) fn map_tells_for_known(config: &FitConfig, known: f64, other: f64) -> bool {
    known - other > config.known_guard || (known > 0.0 && other < config.known_share * known)
}

/// The final refinement of a basin with the map weighted up (`FitConfig::data_weight`), once.
fn weigh_up(problem: &SiteProblem, config: &FitConfig, basin: &mut Basin, index: usize) {
    let Some(weight) = config
        .data_weight
        .filter(|_| config.cartesian_steps > 0 && basin.data_weight == 1.0)
    else {
        return;
    };
    let weighted = supported_atoms(
        problem,
        &basin.x,
        config.support_base,
        config.support_per_torsion,
    );
    if let Some((fit, w)) = refine_weighted_up(
        problem,
        &basin.x,
        basin.template,
        config.cartesian_lr,
        &config.restraints,
        &weight,
        &weighted,
        config.contact_tolerance,
        Some(index),
    ) {
        basin.pose.psi = fit.psi;
        if basin.from_known {
            basin.pose = pose_from_atoms(problem, |i| Some(fit.x[i]), &basin.pose);
        }
        basin.x = fit.x;
        basin.terms = fit.terms;
        basin.e_restraint = fit.e_restraint;
        basin.data_weight = w;
    }
}

/// Make basin `best` the selected one: its support, prior completions, prior deviation and the
/// alternatives within `alt_margin` of it (`fit_site` calls this for the lowest-objective basin;
/// the workflow again when that one fails validation and an alternative passes).
pub fn reselect(
    problem: &SiteProblem,
    sampler: &Sampler,
    config: &FitConfig,
    outcome: &mut FitOutcome,
    best: usize,
) -> Result<()> {
    weigh_up(problem, config, &mut outcome.basins[best], best);
    let basins = &outcome.basins;
    let support = subtree_support(
        problem,
        &basins[best].x,
        config.support_base,
        config.support_per_torsion,
    );
    let free = unsupported_torsions(problem, &support);
    let completions = if free.iter().any(|f| *f) {
        complete_from_prior(
            problem,
            sampler,
            &basins[best].pose,
            &free,
            config.n_completions,
            config.flow_steps,
            config.completion_guidance,
            config.seed,
        )?
    } else {
        Vec::new()
    };
    let energy = |i: usize| basins[i].objective;
    let alternatives = outcome
        .order
        .iter()
        .copied()
        .filter(|&i| i == best || energy(i) - energy(best) <= config.alt_margin)
        .collect();
    outcome.prior_deviation = prior_deviation(problem, &basins[best].x);
    outcome.best = best;
    outcome.support = support;
    outcome.free_torsions = free;
    outcome.completions = completions;
    outcome.alternatives = alternatives;
    Ok(())
}

/// Refine the `top` lowest-objective poses (Adam) and keep improvements.
fn polish_top(
    problem: &SiteProblem,
    poses: &mut [Pose],
    energies: &mut [f64],
    top: usize,
    steps: usize,
    lr: f64,
) {
    let mut order: Vec<usize> = (0..energies.len()).collect();
    order.sort_by(|&a, &b| energies[a].total_cmp(&energies[b]));
    let top: Vec<usize> = order.into_iter().take(top).collect();
    let starts: Vec<Pose> = top.iter().map(|&i| poses[i].clone()).collect();
    for (&i, (pose, e)) in top.iter().zip(refine(problem, &starts, steps, lr)) {
        if e < energies[i] {
            poses[i] = pose;
            energies[i] = e;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_map_tells_for_known_positions_by_a_margin_or_by_a_share() {
        let config = FitConfig::default();
        // far apart in absolute terms
        assert!(map_tells_for_known(&config, 120.0, 105.0));
        // close in absolute terms, but the other basin keeps less than the share
        assert!(map_tells_for_known(&config, 20.0, 14.0));
        assert!(!map_tells_for_known(&config, 20.0, 16.0));
        // the other basin fits the map as well or better
        assert!(!map_tells_for_known(&config, 20.0, 21.0));
        // a map that says nothing of either tells for neither
        assert!(!map_tells_for_known(&config, -4.0, -3.5));
        assert!(!map_tells_for_known(&config, 0.0, -1.0));
    }

    #[test]
    fn known_positions_stay_when_the_map_cannot_tell_or_tells_for_them() {
        let config = FitConfig::default();
        // within the margin of the lowest basin
        assert!(keeps_known(&config, config.alt_margin, 20.0, 20.0));
        // further off by the priors, the map telling for them
        assert!(keeps_known(&config, 40.0, 20.0, 9.0));
        // further off by the priors, the map not telling
        assert!(!keeps_known(&config, 40.0, 20.0, 19.0));
    }
}
